"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["46419"],{83663(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_fada.fator_invalido","status":422,"titulo":"O multiplicador do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA) deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_fada.fator_invalido","requisitos":[],"oQueAconteceu":["O `fator` informado na declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso \xe9 zero\\nou negativo. O fator \xe9 o multiplicador aplicado \xe0 nota final, depois dos pesos (por exemplo,\\n`1,2000`); s\xf3 vale um n\xfamero maior que zero.","A recusa vem no campo `fator` e acumula, na mesma resposta, com as demais viola\xe7\xf5es dos\\nvalores do fator, em\\n[`teto_invalido`](/erros/uniplus.selecao.configuracao_do_fada.teto_invalido) e\\n[`fato_elegibilidade_invalido`](/erros/uniplus.selecao.configuracao_do_fada.fato_elegibilidade_invalido).\\nEla vem depois da confer\xeancia da regra e da base legal; se alguma delas falhar, os valores\\nnem chegam a ser conferidos.","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na declara\xe7\xe3o, informe um `fator` maior que zero, com o valor que o edital fixa para o\\nmultiplicador.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do fada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);